import {tmpdir} from 'node:os';import {run} from '../../engine/pipeline.mjs';
import assert from 'node:assert/strict';import {readFile,writeFile,mkdtemp,cp,rm} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';import {serveStatic} from '../../engine/static.mjs';
const artifact=path.resolve(process.argv[2]||'artifacts/platform/ultimate-installed'),temp=await mkdtemp(path.join(tmpdir(),'ultimate-export-')),results=[];let server,browser;
try{await cp(path.join(artifact,'project'),temp,{recursive:true});for(const name of ['component-addon-navigation.js','component-export.mjs','component-markup.mjs'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(temp,'scripts',name));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});for(const layout of ['horizontal','vertical','expandible'])for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900}});page.setDefaultTimeout(12000);const external=[];await page.route('**/*',r=>{if(new URL(r.request().url()).origin===server.url)return r.continue();external.push(r.request().url());return r.abort();});await page.goto(server.url+'/menu-'+layout+'/',{waitUntil:'networkidle'});const widget=page.locator('.elementor-widget-navigation-menu');assert.equal(await widget.count(),1);await widget.scrollIntoViewIfNeeded();await widget.locator('[data-cloner-addon-menu-ready=true]').waitFor({state:'attached'});const toggle=widget.locator('.hfe-nav-menu__toggle'),nav=widget.locator('nav'),button=widget.locator('.hfe-has-submenu-container').first(),submenu=widget.locator('.sub-menu').first();
 await widget.screenshot({path:path.join(artifact,'menu-'+layout+'-'+width+'-closed.png')});const toggleVisible=await toggle.isVisible();if(toggleVisible)await toggle.click();if(layout==='horizontal'&&width===1440)await button.hover();else await button.click();assert.equal(await submenu.isVisible(),true);await page.waitForTimeout(350);const a=await widget.boundingBox(),b=await submenu.boundingBox(),x=Math.floor(Math.min(a.x,b.x)),y=Math.floor(Math.min(a.y,b.y));await page.screenshot({path:path.join(artifact,'menu-'+layout+'-'+width+'-open.png'),clip:{x,y,width:Math.ceil(Math.max(a.x+a.width,b.x+b.width)-x),height:Math.ceil(Math.max(a.y+a.height,b.y+b.height)-y)}});
 await button.focus();await page.keyboard.press('Escape');assert.equal(await submenu.isVisible(),false);await page.keyboard.press('Enter');assert.equal(await submenu.isVisible(),true);if(toggleVisible){await toggle.focus();await page.keyboard.press(' ');assert.equal(await nav.isVisible(),false);}assert.deepEqual(external,[]);results.push({layout,width,toggleVisible,submenuOpen:true,escapeAndEnter:true,localAssets:true});await page.close();}await writeFile(path.join(artifact,'ultimate-export-check.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
